@module bridge  src=bridge.lua  loc=244  mode=chunk  self=bridge

# Invariants & contracts
  @contract  tick() is the only entry; execute/render/scan are internal. Deps: { env, spoolDir? }.  @ 3
  @invariant  a bad chunk never escapes — load failure and runtime error both land in the res file  @ 4
  @invariant  request file is read then deleted BEFORE execute, so a mid-chunk crash cannot replay it  @ 5
  @invariant  chunk env = deps.env over a _G fallback (stdlib+reaper); chunk global writes stay in env  @ 6
  @invariant  dormant until the spool dir exists (re-stat ~60 frames); once enabled, stays enabled  @ 7
  @invariant  reload() only flags; the relaunch runs on the NEXT tick, after the response is on disk  @ 8
  @invariant  records our named command id in spool/action.id — the launcher's only way to find it  @ 9
  @reaper  EnumerateFiles caches per-dir; each scan invalidates with idx -1, else stale/deleted reqs linger  @ 10

# Shapes
  @shape  response = "status: ok|error\nms: N\n--- value ---\n<render>\n--- print ---\n<buffered>\n"  @ 11

# Imports
  @require util = 'util'  @ 13

# Private state
  @state deps = ... or {}  @ 15
  @state env = deps.env or {}  @ 16
  @state spoolDir = deps.spoolDir or defaultSpoolDir()  @ 25
  @state printBuf = {}  @ 29
  @state bootTime = reaper.time_precise and reaper.time_precise() or os.clock()  @ 38
  @state pendingReload = false  @ 39
  @state DEFAULTS = { depth = 4, entries = 40, str = 200, total = 64 * 1024 }  @ 76
  @state CAP = {}  @ 77   -- sentinel thrown when the total byte cap is exceeded
  @state bridge = {}  @ 228
  @state enabled, cooldown = false, 0  @ 229

# Private functions
  @fn defaultSpoolDir()  @ 21-24
  -- Small IO
  @fn join(name)  @ 47
  @fn readAll(path)  @ 49-52
  @fn writeAtomic(path, text)  @ 54-59
  @fn dirExists(path)  @ 61-64
  @fn nowMs()  @ 66-69
  -- Render
  @fn render(value, opts)  @ 79-128
  -- Directives
  @fn parseDirectives(code)  @ 132-144
  -- Execute
  @fn execute(rawCode)  @ 148-173
  @fn formatResponse(r)  @ 175-182
  -- Scan
  @fn firstReq()  @ 186-197
  @fn scanOnce()  @ 199-206
  -- Reload
  @fn relaunch()  @ 212-216
      -- Re-invoking our own action restarts the script; flag 1 auto-terminates the
      -- running instance, flag 2 re-launches it. See docs/bridge.md § Reload.
  @fn recordAction()  @ 220-223
      -- continuum_launcher.lua starts Continuum when nothing is running, so it
      -- cannot ask a live instance which action that is. See docs/bridge.md § Spawning.

# Functions held in tables
  @held env.print(...)  @ 30-34
